function buildDsa(){return DSA_STEPS.map(function(g){var items=[];g.items.forEach(function(s){var ps=A2ZMAP[s.id];if(!ps){items.push(s);return;}s.step=g.name;s.n=ps.length;SECTIONS.push(s);ps.forEach(function(p,i){items.push({id:'p'+s.id.slice(1)+'_'+(i+1),t:p[0],w:s.w,p:true,diff:p[1],u:p[2],v:p[3]||'',sec:s.id,secName:s.t});});});return G(g.name,items);});}
